E.G.

float xpos, ypos, r;

void setup() {

size(800, 800);

xpos = width/2;

ypos = height/2;

r = 25;

}

void draw() {

background(255);

pushMatrix();

scale(2.0);

translate(-width/4, -height/4);

if(sqrt(sq(xpos - mouseX) + sq(ypos - mouseY)) < r) fill(255, 0, 0);

else fill(0, 0, 255);

rect(xpos - r, ypos - r, r*2, r*2);

